CREATE OR REPLACE FUNCTION public.home_revision_preview_data(p_workspace uuid, p_listing uuid, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid;d zoi.home_designs;s jsonb;e jsonb;identity jsonb;token uuid:=gen_random_uuid();BEGIN
 actor:=zoi.home_content_authorize(p_workspace,p_listing);
 SELECT * INTO d FROM zoi.home_designs WHERE listing_id=p_listing AND workspace_id=p_workspace FOR UPDATE;
 IF NOT FOUND OR NOT d.staged OR d.version IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'home_revision_conflict';END IF;
 s:=public.home_content_get(p_workspace,p_listing);
 IF d.content_baseline IS DISTINCT FROM (SELECT zoi.home_revision_baseline(l)FROM zoi.listings l WHERE l.id=p_listing) THEN RAISE EXCEPTION 'home_revision_source_conflict';END IF;
 SELECT jsonb_build_object('name',l.name,'slug',l.slug,'canonical_slug',l.slug,'address',l.address,'city',l.city,'country',l.country)INTO identity FROM zoi.listings l WHERE l.id=p_listing;
 e:=(s->'base')||identity||(d.draft_content->'base')||jsonb_build_object('id',p_listing,'publish_status','published','marketplace_status','','profile',((s->'profile')-ARRAY(SELECT jsonb_array_elements_text(coalesce(d.draft_content->'profile_remove','[]'))))||(d.draft_content->'profile'),'entity_type',s->>'entity_type','category_slug',s->>'category_slug','owner_content',coalesce(s->'owner_content','{}')||(d.draft_content->'base')||jsonb_build_object('profile',(coalesce(s#>'{owner_content,profile}','{}')-ARRAY(SELECT jsonb_array_elements_text(coalesce(d.draft_content->'profile_remove','[]'))))||(d.draft_content->'profile')));
 IF d.draft_content->>'media_remove'='true' THEN e:=jsonb_set(e,'{profile}',(e->'profile')-'owner_media');END IF;
 IF d.draft_content?'media' THEN e:=jsonb_set(e,'{profile,owner_media}',jsonb_build_object('version',coalesce((s#>>'{profile,owner_media,version}')::integer,0)+1,'items',d.draft_content->'media'));END IF;
 UPDATE zoi.home_designs SET preview_receipt=jsonb_build_object('id',token,'actor',actor,'revision',p_revision,'baseline',d.content_baseline,'expires_at',clock_timestamp()+interval '30 minutes','renderer','home-revision-v1','ready',false)WHERE workspace_id=p_workspace AND listing_id=p_listing;
 RETURN jsonb_build_object('ok',true,'workspace_id',p_workspace,'listing_id',p_listing,'revision',p_revision,'preview_id',token,'entity',e,'design',d.draft);
END $function$

CREATE OR REPLACE FUNCTION zoi.home_content_get_before_revision(p_workspace uuid, p_listing uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l zoi.listings;p jsonb;
BEGIN PERFORM zoi.home_content_authorize(p_workspace,p_listing);SELECT * INTO l FROM zoi.listings WHERE id=p_listing;
 p:=coalesce(l.profile,'{}')-'_coverage';IF p?'_enrich' THEN p:=jsonb_set(p,'{_enrich}',(p->'_enrich')-'lease');END IF;
 RETURN jsonb_build_object('ok',true,'workspace_id',p_workspace,'listing_id',p_listing,'version',zoi.home_content_version(l),'base',public.bizpage_get(p_workspace,p_listing),'profile',p,'owner_content',coalesce(zoi.public_owner_content(l.id),'{}'::jsonb),'entity_type',l.entity_type,'category_slug',(SELECT slug FROM zoi.categories WHERE id=l.primary_category_id));
END $function$

CREATE OR REPLACE FUNCTION public.home_entity(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entity jsonb; published jsonb;
begin
 entity:=public.seo_entity(p_slug);
 if entity is null or entity->>'id' is null then return entity;end if;
 if not exists(select 1 from zoi.listings where id=(entity->>'id')::uuid and publish_status='published' and moderation_status in ('clean','cleared') and coalesce(marketplace_status,'')<>'hidden') then return null;end if;
 published:=public.home_design_public((entity->>'id')::uuid);
 return entity||jsonb_build_object('published_design',published);
end $function$

CREATE OR REPLACE FUNCTION zoi.assert_workspace_write(p_workspace uuid, p_roles text[] DEFAULT ARRAY['owner'::text, 'admin'::text, 'editor'::text])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text;
begin r:=zoi.workspace_locked_role(p_workspace);
 if not coalesce(r=any(p_roles),false) then raise exception 'insufficient_permission' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION zoi.home_content_authorize(p_workspace uuid, p_listing uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=zoi.org_actor();owner_ws uuid;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 -- Verify the current account/session before any caller can return an old receipt.
 PERFORM zoi.workspace_invitation_email(false);
 PERFORM 1 FROM zoi.user_profiles WHERE id=actor FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM zoi.user_profiles WHERE id=actor AND auth_user_id=auth.uid()) THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 -- The guard is VOLATILE and uses fresh statements after every existing lock wait.
 PERFORM zoi.workspace_invitation_email(false);
 PERFORM 1 FROM zoi.workspace_members WHERE workspace_id=p_workspace AND profile_id=actor AND role IN('owner','admin','editor')FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);
 SELECT owner_workspace_id INTO owner_ws FROM zoi.listings WHERE id=p_listing FOR UPDATE;
 IF NOT FOUND OR (owner_ws IS NOT NULL AND owner_ws<>p_workspace) OR NOT zoi.bizpage_can_edit(p_workspace,p_listing)THEN RAISE EXCEPTION 'no_access_to_listing' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);
 IF owner_ws IS NULL THEN PERFORM 1 FROM zoi.listing_claims WHERE listing_id=p_listing AND workspace_id=p_workspace AND claim_status IN('approved','verified')FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'no_access_to_listing' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION zoi.suite_current_session()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid text:=auth.jwt()->>'session_id';
begin
 if auth.uid() is null or coalesce(sid,'') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.users where id=auth.uid() and deleted_at is null and coalesce(is_anonymous,false)=false and (banned_until is null or banned_until<=clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.sessions where id=sid::uuid and user_id=auth.uid() and (not_after is null or not_after>clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
end $function$
